import React, { useEffect, useState } from 'react';
import './Carrito.css';
import NavMenu from '../../navMenu/NavMenu';
import Loading from '../../loading/Loading';
import { FaTrash } from 'react-icons/fa';
import { getCartItems, removeFromCart, updateCartItemQuantity } from '../Carrito_Localstorang/CaritoLocalstorang';
import { setUserData, getUserData } from '../../Usuario/LocalStorangUser/LocalstorangUser';
import { initMercadoPago } from '@mercadopago/sdk-react';
import { Compra, Buscar_Tienda, Create_Order, LogalstorangUSER } from '../../../Redux/Actions/Usuario/Action-user';
import { useDispatch, useSelector } from 'react-redux';
import alertify from 'alertifyjs';
import 'alertifyjs/build/css/alertify.css';
import { useNavigate } from 'react-router-dom';

const Carrito = () => {
  const user = useSelector(state => state.USER);
  const [loading, setLoading] = useState(true);
  const [cartItems, setCartItems] = useState([]);
  const [order, setOrder] = useState(false);
  const [urlcompras, setUrlcompras] = useState('');
  const dispatch = useDispatch();
  const navigate = useNavigate();
  initMercadoPago('APP_USR-ca102d50-c4cd-4152-8963-dee46e25e589');

  useEffect(() => {
    const storedUser = getUserData();

    if (!user || user.state === 'false') {
      if (!storedUser || storedUser.state === 'false') {
        navigate('/');
      } else {
        dispatch(LogalstorangUSER(storedUser));
      }
    } else {
      setUserData(user);
    }
  }, [navigate, user, dispatch]);

  useEffect(() => {
    const timer = setTimeout(() => {
      setLoading(false);
    }, 3000);

    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    const items = getCartItems();
    setCartItems(items);
  }, []);

  const handleRemoveItem = (id) => {
    removeFromCart(id);
    setCartItems(getCartItems());
  };

  const handleUpdateQuantity = (id, quantity) => {
    updateCartItemQuantity(id, quantity);
    setCartItems(getCartItems());
  };

  const calculateTotal = () => {
    return cartItems.reduce((total, item) => total + item.costo * item.quantity, 0);
  };

  const handleCrearOrden = async () => {
    try {
      const cartItems = getCartItems();

      const grouped = cartItems.reduce((acc, item) => {
        if (!acc[item.tienda]) {
          acc[item.tienda] = [];
        }
        acc[item.tienda].push(item);
        return acc;
      }, {});

      const orders = [];
      let totalCostGlobal = 0;
      let totalItems = 0;
      let descriptionsGlobal = '';

      for (const [tienda, items] of Object.entries(grouped)) {
        const totalCost = items.reduce((total, item) => total + item.costo * item.quantity, 0);
        const cantidad = items.reduce((total, item) => total + item.quantity, 0);
        const descriptions = items.map(item => item.descripcion).join(', ');

        totalCostGlobal += totalCost;
        totalItems += cantidad;
        descriptionsGlobal += descriptions + ', ';

        orders.push({ tienda, items, totalCost });
      }

      descriptionsGlobal = descriptionsGlobal.slice(0, -2);

      const compra = await dispatch(Compra(descriptionsGlobal, totalItems, totalCostGlobal));
      setUrlcompras(compra);

      const order = await dispatch(Create_Order(compra, cartItems, totalCostGlobal, 'false', 'Registrada'));

      alertify.alert('Orden creada', `Orden ID: ${order}, ID de compra: ${compra}`);

      setOrder(true);
    } catch (error) {
      console.error(error);
      alertify.alert('Error', 'No se pudo crear la preferencia de pago.');
    }
  };

  const handleCancelarOrden = () => {
    setOrder(false);
  };

  return (
    <div>
      {loading && <Loading />}
      <NavMenu className="nav-menu" />
      <div className="CarritoBody">
        <div className="Carrito-cards">
          <div className="Carrito-cards-titulo">
            <h1>Carrito de Compras</h1>
          </div>
          <div className="Carrito-cards-contenido">
            {cartItems.length === 0 ? (
              <div className="no-items-message">No hay elementos en el carrito</div>
            ) : order === false ? (
              cartItems.map(item => (
                <div key={item.id} className="carrito-item-general">
                  <img src={item.url} alt="Imagen del item para venta" className="carrito-imagen-item" />
                  <div className="item-card-contenido">
                    <div>{item.marca}</div>
                    <div>${item.costo}</div>
                    <div>{item.calidad}</div>
                    <div>Talla: {item.talla}</div>
                    <div>
                      <FaTrash className="btn-carrito" onClick={() => handleRemoveItem(item.id)} />
                      <button className="btn-carrito" onClick={() => handleUpdateQuantity(item.id, item.quantity - 1)}>-</button>
                      <input type="text" className="input-carrito" value={item.quantity} readOnly />
                      <button className="btn-carrito" onClick={() => handleUpdateQuantity(item.id, item.quantity + 1)}>+</button>
                    </div>
                    <div>Costo: ${item.costo * item.quantity}</div>
                  </div>
                </div>
              ))
            ) : (
              <>
                <h1>Orden Creada</h1>
                <div className="orden-creada">
                  {cartItems.map(item => (
                    <div key={item.id} className="orden-item">
                      <div>{item.descripcion}</div>
                      <div>${item.costo * item.quantity}</div>
                    </div>
                  ))}
                  <div className="total-cost">
                    <strong>Total Costo: ${calculateTotal()}</strong>
                  </div>
                </div>
                <div className="cancelar-orden">
                  <button className="btn-carrito-order" onClick={handleCancelarOrden}>Cancelar Orden</button>
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Carrito;
